def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]
    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_c = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
    opp_def = n - opp_c

    d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            d_streak += 1
        else:
            break

    start5 = max(0, n - 5)
    recent5_def = 0
    for i in range(start5, n):
        if history[i][1] == 'D':
            recent5_def += 1

    start10 = max(0, n - 10)
    recent10_def = 0
    for i in range(start10, n):
        if history[i][1] == 'D':
            recent10_def += 1

    forgiven = 0
    punished = 0
    recent_forgiven = 0
    recent_punished = 0
    start20 = max(0, n - 20)
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C':
            if history[i + 1][1] == 'C':
                forgiven += 1
                if i + 1 >= start20:
                    recent_forgiven += 1
            else:
                punished += 1
                if i + 1 >= start20:
                    recent_punished += 1

    if opp_last == 'C':
        if (opp_def <= 2 and recent10_def == 0 and
                punished <= 1 and recent_punished == 0):
            if forgiven >= 3 or recent_forgiven >= 2:
                return 'D'
            if n >= 8:
                return 'D' if my_last == 'C' else 'C'

        if opp_def <= 3 and recent10_def <= 1:
            if my_last == 'D' and forgiven > punished and rng.randint(0, 6) == 0:
                return 'D'
            return 'C'

        if recent10_def >= 5:
            return 'D'

        if opp_def <= 6 and recent10_def <= 3:
            return 'C'

        if rng.randint(0, 7) == 0:
            return 'D'
        return 'C'

    if n >= 95 and d_streak >= 2:
        return 'D'

    if opp_def <= 2 and recent5_def <= 1 and d_streak <= 1:
        if (my_last == 'C' and forgiven >= 2 and punished <= forgiven and
                recent_punished == 0 and rng.randint(0, 3) == 0):
            return 'D'
        return 'C'

    if opp_def <= 4 and recent5_def <= 2 and d_streak <= 2:
        if my_last == 'D':
            if d_streak >= 2 and n < 8:
                return 'D'
            return 'C'
        if (my_last == 'C' and forgiven >= 2 and punished <= forgiven and
                recent_punished == 0 and rng.randint(0, 4) == 0):
            return 'D'
        return 'C'

    if d_streak >= 3 and d_streak < n and opp_def * 2 < n:
        if n < 95 and rng.randint(0, 6) == 0:
            return 'C'

    if my_last == 'D' and d_streak >= 2 and d_streak < n and opp_def <= 6:
        if n < 95 and rng.randint(0, 9) == 0:
            return 'C'

    return 'D'
